window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-11efe208d35add32"]={"versions": [{"id": "FIG-11efe208d35add32", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des synchronen Initialisierungsdienstes <code>Ea_Init</code> innerhalb der AUTOSAR-Basissoftware (Classic Platform). Das Diagramm veranschaulicht das Zusammenspiel zwischen dem System- und Zustandsmanagement (<code>EcuM</code>) und der EEPROM-Abstraktion (<code>Ea</code>) im Steuergeräte-Hochlauf.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei BSW-Module als Lebenslinien (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li><code>EcuM</code>: ECU State Manager als Aufrufer des Initialisierungsdienstes.\n</li><li><code>Ea</code>: EEPROM Abstraction als aufgerufenes Modul der Speicherdienst-Abstraktionsschicht.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li>Synchroner Operationsaufruf <code>Ea_Init()</code> von <code>EcuM</code> an <code>Ea</code>.\n</li><li>Rückkehrnachricht (Return) <code>Ea_Init()</code> von <code>Ea</code> an <code>EcuM</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>EcuM</code> stößt den synchronen Aufruf <code>Ea_Init()</code> an der Lebenslinie von <code>Ea</code> an.\n</li><li>Das Modul <code>Ea</code> führt auf seinem Aktivierungsbalken die interne Initialisierung durch.\n</li><li>Nach Abschluss der Initialisierungslogik erfolgt die Rückkehr (<code>Ea_Init()</code>) synchron über die gestrichelte Pfeillinie zurück an <code>EcuM</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Aufruf <code>Ea_Init()</code> erfolgt im Hochlaufkontext (Startup-Phase des <code>EcuM</code>). In dieser Spezifikationsfassung wird <code>Ea_Init()</code> parameterlos aufgerufen; das Modul greift intern auf seine Vorkonfiguration bzw. Link-Time-/Post-Build-Datenstrukturen zu. Aufrufe weiterer Untermodule während der Initialisierung (wie EEPROM-Treiber) sind in dieser Sequenz nicht modelliert.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c2373ad290992556", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des synchronen Initialisierungsdienstes <code>Ea_Init</code> innerhalb der AUTOSAR-Basissoftware (Classic Platform). Das Diagramm veranschaulicht das Zusammenspiel zwischen dem System- und Zustandsmanagement (<code>EcuM</code>) und der EEPROM-Abstraktion (<code>Ea</code>) im Steuergeräte-Hochlauf.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei BSW-Module als Lebenslinien (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li><code>EcuM</code>: ECU State Manager als Aufrufer des Initialisierungsdienstes.\n</li><li><code>Ea</code>: EEPROM Abstraction als aufgerufenes Modul der Speicherdienst-Abstraktionsschicht.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li>Synchroner Operationsaufruf <code>Ea_Init()</code> von <code>EcuM</code> an <code>Ea</code>.\n</li><li>Rückkehrnachricht (Return) <code>Ea_Init()</code> von <code>Ea</code> an <code>EcuM</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>EcuM</code> stößt den synchronen Aufruf <code>Ea_Init()</code> an der Lebenslinie von <code>Ea</code> an.\n</li><li>Das Modul <code>Ea</code> führt auf seinem Aktivierungsbalken die interne Initialisierung durch.\n</li><li>Nach Abschluss der Initialisierungslogik erfolgt die Rückkehr (<code>Ea_Init()</code>) synchron über die gestrichelte Pfeillinie zurück an <code>EcuM</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Aufruf <code>Ea_Init()</code> erfolgt im Hochlaufkontext (Startup-Phase des <code>EcuM</code>). In dieser Spezifikationsfassung wird <code>Ea_Init()</code> parameterlos aufgerufen; das Modul greift intern auf seine Vorkonfiguration bzw. Link-Time-/Post-Build-Datenstrukturen zu. Aufrufe weiterer Untermodule während der Initialisierung (wie EEPROM-Treiber) sind in dieser Sequenz nicht modelliert.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ff6858dedd1d5e1e", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des synchronen Initialisierungsdienstes <code>Ea_Init</code> innerhalb der AUTOSAR-Basissoftware (Classic Platform). Das Diagramm veranschaulicht das Zusammenspiel zwischen dem System- und Zustandsmanagement (<code>EcuM</code>) und der EEPROM-Abstraktion (<code>Ea</code>) im Steuergeräte-Hochlauf.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei BSW-Module als Lebenslinien (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li><code>EcuM</code>: ECU State Manager als Aufrufer des Initialisierungsdienstes.\n</li><li><code>Ea</code>: EEPROM Abstraction als aufgerufenes Modul der Speicherdienst-Abstraktionsschicht.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li>Synchroner Operationsaufruf <code>Ea_Init(const Ea_ConfigType*)</code> von <code>EcuM</code> an <code>Ea</code> (im Diagramm zweizeilig über dem Aufrufpfeil).\n</li><li>Rückkehrnachricht (Return) <code>Ea_Init()</code> von <code>Ea</code> an <code>EcuM</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>EcuM</code> stößt den synchronen Aufruf <code>Ea_Init(const Ea_ConfigType*)</code> an der Lebenslinie von <code>Ea</code> unter Übergabe des Konfigurationszeigers an.\n</li><li>Das Modul <code>Ea</code> führt auf seinem Aktivierungsbalken die interne Initialisierung anhand der übergebenen Konfigurationsdaten durch.\n</li><li>Nach Abschluss der Initialisierungslogik erfolgt die Rückkehr (<code>Ea_Init()</code>) synchron über die gestrichelte Pfeillinie zurück an <code>EcuM</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Dienst <code>Ea_Init</code> erfordert zur Initialisierung die Übergabe eines Zeigers auf die Post-Build- bzw. Initialisierungskonfiguration (<code>const Ea_ConfigType*</code>). Der Aufrufer <code>EcuM</code> muss sicherstellen, dass vor dem Aufruf eine gültige Konfigurationsstruktur referenziert wird. Der Rückkehrpfeil trägt formal weiterhin den Bezeichner <code>Ea_Init()</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-94458ae1b8d2b58d", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des synchronen Initialisierungsdienstes <code>Ea_Init</code> innerhalb der AUTOSAR-Basissoftware (Classic Platform). Das Diagramm veranschaulicht das Zusammenspiel zwischen dem System- und Zustandsmanagement (<code>EcuM</code>) und der EEPROM-Abstraktion (<code>Ea</code>) im Steuergeräte-Hochlauf.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei BSW-Module als Lebenslinien (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li><code>EcuM</code>: ECU State Manager als Aufrufer des Initialisierungsdienstes.\n</li><li><code>Ea</code>: EEPROM Abstraction als aufgerufenes Modul der Speicherdienst-Abstraktionsschicht.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li>Synchroner Operationsaufruf von <code>EcuM</code> an <code>Ea</code>, visuell überlagert dargestellt als Textblock mit <code>Ea_Init</code> / <code>(const Ea_Config...</code> / <code>Ea_Init()</code>.\n</li><li>Rückkehrnachricht (Return) von <code>Ea</code> an <code>EcuM</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>EcuM</code> stößt den synchronen Aufruf <code>Ea_Init(const Ea_ConfigType*)</code> an der Lebenslinie von <code>Ea</code> unter Übergabe des Konfigurationszeigers an.\n</li><li>Das Modul <code>Ea</code> führt auf seinem Aktivierungsbalken die interne Initialisierung anhand der übergebenen Konfigurationsdaten durch.\n</li><li>Nach Abschluss der Initialisierungslogik erfolgt die Rückkehr (<code>Ea_Init()</code>) synchron über die gestrichelte Pfeillinie zurück an <code>EcuM</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Dienst <code>Ea_Init</code> erfordert zur Initialisierung die Übergabe eines Zeigers auf die Post-Build- bzw. Initialisierungskonfiguration (<code>const Ea_ConfigType*</code>). Der Aufrufer <code>EcuM</code> muss sicherstellen, dass vor dem Aufruf eine gültige Konfigurationsstruktur referenziert wird. Der Rückkehrpfeil trägt formal weiterhin den Bezeichner <code>Ea_Init()</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-431891f36421ec28", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des synchronen Initialisierungsdienstes <code>Ea_Init</code> innerhalb der AUTOSAR-Basissoftware (Classic Platform). Das Diagramm veranschaulicht das Zusammenspiel zwischen dem System- und Zustandsmanagement (<code>EcuM</code>) und der EEPROM-Abstraktion (<code>Ea</code>) im Steuergeräte-Hochlauf.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei BSW-Module als Lebenslinien (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li><code>EcuM</code>: ECU State Manager als Aufrufer des Initialisierungsdienstes.\n</li><li><code>Ea</code>: EEPROM Abstraction als aufgerufenes Modul der Speicherdienst-Abstraktionsschicht.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li>Synchroner Operationsaufruf <code>Ea_Init(const Ea_ConfigType*)</code> von <code>EcuM</code> an <code>Ea</code> (einzeilig über dem Aufrufpfeil dargestellt).\n</li><li>Rückkehrnachricht (Return) <code>Ea_Init()</code> von <code>Ea</code> an <code>EcuM</code> (einzeilig über der Rückkehrlinie).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>EcuM</code> stößt den synchronen Aufruf <code>Ea_Init(const Ea_ConfigType*)</code> an der Lebenslinie von <code>Ea</code> unter Übergabe des Konfigurationszeigers an.\n</li><li>Das Modul <code>Ea</code> führt auf seinem Aktivierungsbalken die interne Initialisierung anhand der übergebenen Konfigurationsdaten durch.\n</li><li>Nach Abschluss der Initialisierungslogik erfolgt die Rückkehr (<code>Ea_Init()</code>) synchron über die gestrichelte Pfeillinie zurück an <code>EcuM</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Dienst <code>Ea_Init</code> erfordert zur Initialisierung die Übergabe eines Zeigers auf die Post-Build- bzw. Initialisierungskonfiguration (<code>const Ea_ConfigType*</code>). Der Aufrufer <code>EcuM</code> muss sicherstellen, dass vor dem Aufruf eine gültige Konfigurationsstruktur referenziert wird. Der Rückkehrpfeil trägt formal weiterhin den Bezeichner <code>Ea_Init()</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f9743c47028c918c", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des synchronen Initialisierungsdienstes <code>Ea_Init</code> innerhalb der AUTOSAR-Basissoftware (Classic Platform). Das Diagramm veranschaulicht das Zusammenspiel zwischen dem System- und Zustandsmanagement (<code>EcuM</code>) und der EEPROM-Abstraktion (<code>Ea</code>) im Steuergeräte-Hochlauf.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei BSW-Module als Lebenslinien (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li><code>EcuM</code>: ECU State Manager als Aufrufer des Initialisierungsdienstes.\n</li><li><code>Ea</code>: EEPROM Abstraction als aufgerufenes Modul der Speicherdienst-Abstraktionsschicht.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li>Synchroner Operationsaufruf <code>Ea_Init(const Ea_ConfigType*)</code> von <code>EcuM</code> an <code>Ea</code> (einzeilig über dem Aufrufpfeil dargestellt).\n</li><li>Rückkehrnachricht (Return) <code>Ea_Init()</code> von <code>Ea</code> an <code>EcuM</code> (einzeilig über der Rückkehrlinie).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>EcuM</code> stößt den synchronen Aufruf <code>Ea_Init(const Ea_ConfigType*)</code> an der Lebenslinie von <code>Ea</code> unter Übergabe des Konfigurationszeigers an.\n</li><li>Das Modul <code>Ea</code> führt auf seinem Aktivierungsbalken die interne Initialisierung anhand der übergebenen Konfigurationsdaten durch.\n</li><li>Nach Abschluss der Initialisierungslogik erfolgt die Rückkehr (<code>Ea_Init()</code>) synchron über die gestrichelte Pfeillinie zurück an <code>EcuM</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Dienst <code>Ea_Init</code> erfordert zur Initialisierung die Übergabe eines Zeigers auf die Post-Build- bzw. Initialisierungskonfiguration (<code>const Ea_ConfigType*</code>). Der Aufrufer <code>EcuM</code> muss sicherstellen, dass vor dem Aufruf eine gültige Konfigurationsstruktur referenziert wird. Der Rückkehrpfeil trägt formal weiterhin den Bezeichner <code>Ea_Init()</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-98a07ba865aaf11a", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des synchronen Initialisierungsdienstes <code>Ea_Init</code> innerhalb der AUTOSAR-Basissoftware (Classic Platform). Das Diagramm veranschaulicht das Zusammenspiel zwischen dem System- und Zustandsmanagement (<code>EcuM</code>) und der EEPROM-Abstraktion (<code>Ea</code>) im Steuergeräte-Hochlauf.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei BSW-Module als Lebenslinien (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li><code>EcuM</code>: ECU State Manager als Aufrufer des Initialisierungsdienstes.\n</li><li><code>Ea</code>: EEPROM Abstraction als aufgerufenes Modul der Speicherdienst-Abstraktionsschicht.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li>Synchroner Operationsaufruf <code>Ea_Init(const Ea_ConfigType*)</code> von <code>EcuM</code> an <code>Ea</code> (einzeilig über dem Aufrufpfeil dargestellt).\n</li><li>Rückkehrnachricht (Return) <code>Ea_Init()</code> von <code>Ea</code> an <code>EcuM</code> (einzeilig über der Rückkehrlinie).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>EcuM</code> stößt den synchronen Aufruf <code>Ea_Init(const Ea_ConfigType*)</code> an der Lebenslinie von <code>Ea</code> unter Übergabe des Konfigurationszeigers an.\n</li><li>Das Modul <code>Ea</code> führt auf seinem Aktivierungsbalken die interne Initialisierung anhand der übergebenen Konfigurationsdaten durch.\n</li><li>Nach Abschluss der Initialisierungslogik erfolgt die Rückkehr (<code>Ea_Init()</code>) synchron über die gestrichelte Pfeillinie zurück an <code>EcuM</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Dienst <code>Ea_Init</code> erfordert zur Initialisierung die Übergabe eines Zeigers auf die Post-Build- bzw. Initialisierungskonfiguration (<code>const Ea_ConfigType*</code>). Der Aufrufer <code>EcuM</code> muss sicherstellen, dass vor dem Aufruf eine gültige Konfigurationsstruktur referenziert wird. Der Rückkehrpfeil trägt formal weiterhin den Bezeichner <code>Ea_Init()</code>.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-11efe208d35add32", "to": "FIG-c2373ad290992556", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c2373ad290992556", "to": "FIG-ff6858dedd1d5e1e", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Aufrufoperation von <code>EcuM</code> an <code>Ea</code>: Signatur von parameterlos <code>Ea_Init()</code> zu parameterbehaftet <code>Ea_Init(const Ea_ConfigType*)</code> mit Konfigurationszeiger geändert (im Diagramm zweizeilig als <code>Ea_Init(const</code> und <code>Ea_ConfigType*)</code> dargestellt).\n</li><li>Rückkehrpfeil: Behält die Beschriftung <code>Ea_Init()</code>.\n</li></ul>"}, {"from": "FIG-ff6858dedd1d5e1e", "to": "FIG-94458ae1b8d2b58d", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Aufruf- und Rückkehrbeschriftung: Textüberlagerung/Fehldarstellung im Beschriftungsbereich zwischen Aufruf- und Rückkehrpfeil (<code>Ea_Init (const Ea_Config</code> kollidiert mit <code>Ea_Init()</code>).\n</li></ul>"}, {"from": "FIG-94458ae1b8d2b58d", "to": "FIG-431891f36421ec28", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Aufrufbeschriftung: Bereinigung des Rendering-Fehlers; die Signatur <code>Ea_Init(const Ea_ConfigType*)</code> steht wieder einzeilig sauber über dem Aufrufpfeil.\n</li><li>Rückkehrbeschriftung: Die Beschriftung <code>Ea_Init()</code> steht wieder sauber über der gestrichelten Rückkehrlinie.\n</li></ul>"}, {"from": "FIG-431891f36421ec28", "to": "FIG-f9743c47028c918c", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f9743c47028c918c", "to": "FIG-98a07ba865aaf11a", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
